sp_widget.css:
.header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: #ffffff;
    padding: 10px 20px;
    box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
}

.logo img {
    height: 40px;
}

.search-bar {
    flex-grow: 1;
    margin: 0 20px;
    display: flex;
    align-items: center;
}

.search-bar input {
    width: 100%;
    padding: 8px;
    border-radius: 5px;
    border: 1px solid #ccc;
}

.nav-menu ul {
    list-style: none;
    display: flex;
}

.nav-menu li {
    margin: 0 10px;
}

.nav-menu a {
    text-decoration: none;
    color: #333;
}

.user-profile {
    display: flex;
    align-items: center;
}

.user-profile img {
    height: 35px;
    border-radius: 50%;
    margin-right: 10px;
}

.fa-bell {
    font-size: 18px;
    margin-right: 15px;
}

sp_widget.script:
(function() {
    var user = gs.getUser();
    data.user_name = user.getDisplayName();
   // data.user_avatar = user.getPhoto() || '/no-avatar.png';
})();
